mapper.select:
SELECT COUNT(*)
FROM company_matching
WHERE COM_MATCHING_IDX = #{comMatchingIdx}

SELECT cm.COM_MATCHING_IDX AS comMatchingIdx, js.JOBSEEKER_NAME AS jobseekerName, cm.COM_MATCH_SCORE AS comMatchScore, cm.COM_AI_REASON AS comAiReason, cm.JOB_POSTS_IDX AS jobPostsIdx, cm.JOBSEEKER_IDX AS jobseekerIdx, cp.KEYSKILL AS keySkill, COALESCE(cp.APPLY_MOTIVE, '') AS apply FROM company_matching cm JOIN jobseeker_users js ON js.JOBSEEKER_IDX = cm.JOBSEEKER_IDX LEFT JOIN cover_posts cp ON cp.JOBSEEKER_IDX = cm.JOBSEEKER_IDX WHERE cm.JOBSEEKER_IDX = #{jobseekerIdx}
AND cm.JOB_POSTS_IDX = #{jobPostsIdx}
ORDER BY cm.MATCHING_CREATEAT DESC, cm.COM_MATCHING_IDX DESC LIMIT 1
